// Auto-generated Indonesia province SVG paths (Mercator projection)
// Bounds: lon [94.5, 141.5], lat [-11.2, 6.2]
// SVG viewport: 1000 x 420
// 38 provinces

export const SVG_W = 1000
export const SVG_H = 420
export const LON_MIN = 94.5
export const LON_MAX = 141.5
export const LAT_MIN = -11.2
export const LAT_MAX = 6.2

// Mercator projection helpers
const mercY = (lat: number) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI / 180) / 2))
const MERC_Y_MIN = mercY(-11.2)
const MERC_Y_MAX = mercY(6.2)

export function projectToSvg(lon: number, lat: number): [number, number] {
  const x = (lon - LON_MIN) / (LON_MAX - LON_MIN) * SVG_W
  const my = mercY(lat)
  const y = (1 - (my - MERC_Y_MIN) / (MERC_Y_MAX - MERC_Y_MIN)) * SVG_H
  return [x, y]
}

export interface ProvinceShape {
  name: string       // GeoJSON province name
  cmsName: string    // CMS-compatible name for matching
  code: string       // Province code (BPS)
  path: string       // SVG path data
}

